func:
if (global.get('SYSTEM_SHUTDOWN')) return null;

const bust = Date.now();
const checks = [
  {
    name: 'Home',
    url: 'https://www.shamrockbailbonds.biz/?_psm=' + bust,
    expect: /Shamrock Bail Bonds/i,
    minLen: 5000
  },
  {
    name: 'FA Hub',
    url: 'https://www.shamrockbailbonds.biz/first-appearance?_psm=' + bust,
    expect: /First Appearance Hearing in Florida/i,
    minLen: 3000
  },
  {
    name: 'FA County Lee',
    url: 'https://www.shamrockbailbonds.biz/first-appearance/lee?_psm=' + bust,
    expect: /Lee County/i,
    minLen: 2000
  },
  {
    name: 'FA Embed',
    url: 'https://shamrock-embeds.netlify.app/first-appearance.html?_psm=' + bust,
    expect: /All 67 Florida Counties|COUNTY_FALLBACK|Near me/i,
    minLen: 5000
  },
  {
    name: 'Bail School Embed',
    url: 'https://shamrock-embeds.netlify.app/bail-school.html?_psm=' + bust,
    expect: /Bail School|20-Hour|Correspondence/i,
    minLen: 2000
  },
  {
    name: 'Bail Bonds Lee',
    url: 'https://www.shamrockbailbonds.biz/florida-bail-bonds/lee?_psm=' + bust,
    expect: /Lee County Bail Bonds/i,
    minLen: 2000
  }
];

// Fan out one message per check
return [checks.map(c => ({
  topic: c.name,
  check: c,
  url: c.url,
  method: 'GET',
  headers: {
    'User-Agent': 'ShamrockPublicSiteMonitor/1.0',
    'Accept': 'text/html,application/xhtml+xml'
  },
  followRedirects: true,
  timeout: 15000,
  _started: Date.now()
}))];

const check = msg.check || {};
const name = check.name || msg.topic || 'unknown';
const status = msg.statusCode || 0;
const body = typeof msg.payload === 'string' ? msg.payload : String(msg.payload || '');
const ms = Date.now() - (msg._started || Date.now());
const expect = check.expect || /./;
const re = expect instanceof RegExp ? expect : new RegExp(expect, 'i');

const httpOk = status >= 200 && status < 400;
const bodyOk = body.length >= (check.minLen || 500) && re.test(body);
const ok = httpOk && bodyOk;

const result = {
  name,
  ok,
  status,
  ms,
  bodyLen: body.length,
  url: check.url || msg.url,
  reason: !httpOk ? ('HTTP ' + status) : (!bodyOk ? 'content mismatch / short body' : 'ok')
};

// Aggregate in flow context
let bag = flow.get('psm_results') || {};
bag[name] = result;
flow.set('psm_results', bag);
flow.set('psm_last_run', new Date().toISOString());

// After all expected checks, decide whether to alert
const expected = ['Home','FA Hub','FA County Lee','FA Embed','Bail School Embed','Bail Bonds Lee'];
const got = expected.filter(k => bag[k]);
if (got.length < expected.length) {
  node.status({fill:'blue', shape:'ring', text: got.length + '/' + expected.length});
  return null;
}

const failures = expected.map(k => bag[k]).filter(r => r && !r.ok);
flow.set('psm_results', {}); // reset for next cycle

if (!failures.length) {
  node.status({fill:'green', shape:'dot', text: expected.length + ' OK'});
  global.set('PSM_LAST_OK', new Date().toISOString());
  return null; // silence on green
}

node.status({fill:'red', shape:'ring', text: failures.length + ' DOWN'});
msg.failures = failures;
msg.summary = failures.map(f => `🔴 *${f.name}*: ${f.reason} (${f.status}, ${f.ms}ms)`).join('\n');
return msg;

const token = (global.get('env') && global.get('env').SLACK_BOT_TOKEN) || global.get('SLACK_BOT_TOKEN') || global.get('SLACK_TOKEN') || '';
const when = new Date().toLocaleString('en-US', { timeZone: 'America/New_York' });
msg.headers = {
  Authorization: 'Bearer ' + token,
  'Content-Type': 'application/json; charset=utf-8'
};
msg.payload = {
  channel: '#alerts',
  text: '🚨 Public Site Monitor — failure',
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: '🚨 Public Site Monitor', emoji: true } },
    { type: 'section', text: { type: 'mrkdwn', text: msg.summary || 'Unknown failure' } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: '_Read-only probes · ' + when + ' ET_' }] }
  ]
};
msg.url = 'https://slack.com/api/chat.postMessage';
msg.method = 'POST';
return msg;
